'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var exp10f = require( './../lib' );


// FIXTURES //

var mediumNegative = require( './fixtures/julia/medium_negative.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var smallNegative = require( './fixtures/julia/small_negative.json' );
var smallPositive = require( './fixtures/julia/small_positive.json' );
var tiny = require( './fixtures/julia/tiny.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof exp10f, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function accurately computes `10**x` for negative medium numbers', function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = exp10f( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `10**x` for positive medium numbers', function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = exp10f( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `10**x` for negative small numbers', function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = smallNegative.x;
	expected = smallNegative.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = exp10f( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `10**x` for positive small numbers', function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = smallPositive.x;
	expected = smallPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = exp10f( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes `10**x` for very small `x`', function test( t ) {
	var expected;
	var x;
	var v;
	var e;
	var i;

	x = tiny.x;
	expected = tiny.expected;

	for ( i = 0; i < x.length; i++ ) {
		v = exp10f( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( v, e, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `+infinity` for very large `x`', function test( t ) {
	var val = exp10f( f32( 128.0 ) );
	t.strictEqual( val, PINF, 'returns expected value' );

	val = exp10f( f32( 1000.0 ) );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` for very large negative `x`', function test( t ) {
	var val = exp10f( f32( -150.0 ) );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );

	val = exp10f( f32( -1000.0 ) );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` if provided `-infinity`', function test( t ) {
	var val = exp10f( NINF );
	t.strictEqual( isPositiveZerof( val ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var val = exp10f( PINF );
	t.strictEqual( val, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `1` if provided `+-0`', function test( t ) {
	var val;

	val = exp10f( f32( -0.0 ) );
	t.strictEqual( val, f32( 1.0 ), 'returns expected value' );

	val = exp10f( f32( +0.0 ) );
	t.strictEqual( val, f32( 1.0 ), 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var val = exp10f( NaN );
	t.strictEqual( isnanf( val ), true, 'returns expected value' );
	t.end();
});
